          "code": "def __deepcopy__(self, memo):\n\n\n        cls = self.__class__\n        result = cls.__new__(cls)\n        memo[id(self)] = result\n\n        # New guid\n        result.guid = str(uuid.uuid4())\n\n        # Copy remaining fields\n        result.name = copy.deepcopy(self.name, memo)\n        result._r = self._r\n        result._g = self._g\n        result._b = self._b\n        result._a = self._a\n        return result\n\n    def duplicate(self) -> \"Color\":\n        \"\"\"Create a deep copy of this color with a new GUID.\n\n        Returns\n        -------\n        :class:`Color`\n            A new Color with identical RGBA values but a different GUID.\n\n        \"\"\"\n        result = copy.deepcopy(self)\n        result.guid = str(uuid.uuid4())\n        return result\n\n    ###########################################################################################\n    # No-copy Operators\n    ###########################################################################################\n\n    def __getitem__(self, index):\n        if index == 0:\n            return self._r\n        elif index == 1:\n            return self._g\n        elif index == 2:\n            return self._b\n        elif index == 3:\n            return self._a\n        else:\n            raise IndexError(\"Index out of range\")\n\n    def __setitem__(self, index, value):\n        if index == 0:\n            self._r = value\n        elif index == 1:\n            self._g = value\n        elif index == 2:\n            self._b = value\n        elif index == 3:\n            self._a = value\n        else:\n            raise IndexError(\"Index out of range\")\n\n    ###########################################################################################\n    # Details\n    ###########################################################################################\n\n    def to_unified_array(self) -> list[float]:\n        \"\"\"Convert to normalized float array [0-1].\n\n        Returns\n        -------\n        list[float]\n            Array [r, g, b, a] with values normalized to [0.0, 1.0].\n\n        \"\"\"\n        return [self[0] / 255.0, self[1] / 255.0, self[2] / 255.0, self[3] / 255.0]\n\n    @classmethod\n    def from_unified_array(cls, arr) -> \"Color\":\n        \"\"\"Create color from normalized float values [0-1].\n\n        Parameters\n        ----------\n        arr : list[float]",
