          "code": "pub fn number_of_edges(&self) -> usize {\n        let mut count = 0;\n        let mut seen = std::collections::HashSet::new();\n        for (u, neighbors) in &self.edges {\n            for v in neighbors.keys() {\n                let edge = if u < v {\n                    (u.clone(), v.clone())\n                } else {\n                    (v.clone(), u.clone())\n                };\n                if seen.insert(edge) {\n                    count += 1;\n                }\n            }\n        }\n        count\n    }",
