        "cpp": {
          "sig": "bool is_linear(double tolerance)",
          "code": "bool NurbsCurve::is_linear(double tolerance) const {\n    if (!is_valid() || m_cv_count < 2) return false;\n    \n    Point p0 = get_cv(0);\n    Point p1 = get_cv(m_cv_count - 1);\n    Vector line_vec(p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]);\n    double line_length = line_vec.magnitude();\n    \n    if (line_length < tolerance) return true;\n    \n    for (int i = 1; i < m_cv_count - 1; i++) {\n        Point p = get_cv(i);\n        Vector v(p[0] - p0[0], p[1] - p0[1], p[2] - p0[2]);\n        Vector cross = line_vec.cross(v);\n        double dist = cross.magnitude() / line_length;\n        if (dist > tolerance) return false;\n    }",
          "file": "nurbscurve.cpp"
        },
        "rust": {
          "sig": "is_linear(tolerance: Option<f64>) -> bool",
          "code": "pub fn is_linear(&self, tolerance: Option<f64>) -> bool {\n        let tol = tolerance.unwrap_or(Tolerance::ZERO_TOLERANCE);\n\n        if !self.is_valid() || self.m_cv_count < 2 {\n            return false;\n        }\n\n        if self.m_cv_count == 2 {\n            return true;\n        }\n\n        // Check if all control points are collinear\n        let p0 = self.get_cv(0).unwrap();\n        let p1 = self.get_cv(self.m_cv_count - 1).unwrap();\n\n        let line_vec = Vector::new(p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]);\n        let line_len = line_vec.magnitude();\n\n        if line_len < tol {\n            return true; // Degenerate to a point\n        }\n\n        for i in 1..(self.m_cv_count - 1) {\n            let p = self.get_cv(i).unwrap();\n            let v = Vector::new(p[0] - p0[0], p[1] - p0[1], p[2] - p0[2]);\n\n            // Cross product to check collinearity\n            let cross = line_vec.cross(&v);\n\n            if cross.magnitude() > tol * line_len {\n                return false;\n            }\n        }\n\n        true\n    }",
          "file": "nurbscurve.rs"
        }
