          "code": "pub fn get_next_discontinuity(&self, continuity_type: i32, t0: f64, t1: f64) -> (bool, f64) {\n        if !self.is_valid() || t0 >= t1 {\n            return (false, 0.0);\n        }\n        let (d0, d1) = self.domain();\n        let t0 = t0.max(d0);\n        let t1 = t1.min(d1);\n        if t0 >= t1 {\n            return (false, 0.0);\n        }\n        for i in (self.m_order - 1)..(self.m_cv_count - 1) {\n            let t = self.m_knot[i];\n            if t <= t0 || t >= t1 { continue; }\n            let mult = self.knot_multiplicity(i);\n            if continuity_type == 0 && mult >= self.m_order {\n                return (true, t);\n            }\n            if continuity_type == 1 && mult >= self.m_order - 1 {\n                return (true, t);\n            }\n            if continuity_type == 2 && mult >= self.m_order - 2 {\n                return (true, t);\n            }\n            if (continuity_type == 3 || continuity_type == 4) && mult >= self.m_order - 1 {\n                return (true, t);\n            }\n        }\n        (false, 0.0)\n    }",
