        "python": {
          "sig": "get_cv(i: int, j: int) -> Point",
          "code": "def get_cv(self, i: int, j: int) -> Point:\n\n        \"\"\"Get control point as Point.\n        \n        Parameters\n        ----------\n        i : int\n            Index in u direction.\n        j : int\n            Index in v direction.\n        \n        Returns\n        -------\n        Point\n            Control point at (i, j).\n        \"\"\"\n        cv_ptr = self.cv(i, j)\n        if cv_ptr is None:\n            return Point(0, 0, 0)\n        \n        if self.m_is_rat:\n            w = cv_ptr[self.m_dim]\n            if abs(w) < 1e-14:\n                return Point(0, 0, 0)\n            return Point(cv_ptr[0]/w,\n                        cv_ptr[1]/w if self.m_dim > 1 else 0,\n                        cv_ptr[2]/w if self.m_dim > 2 else 0)\n        \n        return Point(cv_ptr[0],\n                    cv_ptr[1] if self.m_dim > 1 else 0,\n                    cv_ptr[2] if self.m_dim > 2 else 0)\n    \n    def get_cv_4d(self, i: int, j: int) -> Tuple[bool, float, float, float, float]:\n        \"\"\"Get control point as homogeneous coordinates (x, y, z, w).\n        \n        Parameters\n        ----------\n        i : int\n            Index in u direction.\n        j : int\n            Index in v direction.\n        \n        Returns\n        -------\n        tuple\n            (success, x, y, z, w)\n        \"\"\"\n        cv_ptr = self.cv(i, j)\n        if cv_ptr is None:\n            return (False, 0.0, 0.0, 0.0, 1.0)\n        \n        x = cv_ptr[0]\n        y = cv_ptr[1] if self.m_dim > 1 else 0.0\n        z = cv_ptr[2] if self.m_dim > 2 else 0.0\n        w = cv_ptr[self.m_dim] if self.m_is_rat else 1.0\n        \n        return (True, x, y, z, w)\n    \n    def set_cv(self, i: int, j: int, point: Point) -> bool:\n        \"\"\"Set control point from Point.\n        \n        Parameters\n        ----------\n        i : int\n            Index in u direction.\n        j : int\n            Index in v direction.\n        point : Point\n            Point to set.\n        \n        Returns\n        -------\n        bool\n            True if successful, False otherwise.\n        \"\"\"\n        cv_ptr = self.cv(i, j)\n        if cv_ptr is None:\n            return False\n\n        if self.m_is_rat:\n            # For rational surfaces, store homogeneous coordinates (x*w, y*w, z*w, w)",
          "file": "nurbssurface.py"
        },
        "cpp": {
          "sig": "Point get_cv(int i, int j)",
          "code": "Point NurbsSurface::get_cv(int i, int j) const {\n    const double* cv_ptr = cv(i, j);\n    if (!cv_ptr) return Point(0, 0, 0);\n    \n    if (m_is_rat) {\n        double w = cv_ptr[m_dim];\n        if (std::abs(w) < 1e-14) return Point(0, 0, 0);\n        return Point(cv_ptr[0]/w, \n                    m_dim > 1 ? cv_ptr[1]/w : 0,\n                    m_dim > 2 ? cv_ptr[2]/w : 0);\n    }",
          "file": "nurbssurface.cpp"
        },
        "rust": {
          "sig": "get_cv(i: usize, j: usize) -> Option<Point>",
          "code": "pub fn get_cv(&self, i: usize, j: usize) -> Option<Point> {\n        let cv = self.cv(i, j)?;\n        if self.m_is_rat && cv.len() > self.m_dim {\n            let w = cv[self.m_dim];\n            if w.abs() > 1e-14 {\n                Some(Point::new(cv[0] / w, cv[1] / w, cv[2] / w))\n            } else {\n                Some(Point::new(0.0, 0.0, 0.0))\n            }\n        } else {\n            Some(Point::new(\n                if cv.len() > 0 { cv[0] } else { 0.0 },\n                if cv.len() > 1 { cv[1] } else { 0.0 },\n                if cv.len() > 2 { cv[2] } else { 0.0 },\n            ))\n        }\n    }",
          "file": "nurbssurface.rs"
        }
