        "rust": {
          "sig": "set_weight(i: usize, j: usize, w: f64) -> bool",
          "code": "pub fn set_weight(&mut self, i: usize, j: usize, w: f64) -> bool {\n        if !self.m_is_rat {\n            return false;\n        }\n        let dim = self.m_dim;\n        if let Some(cv) = self.cv_mut(i, j) {\n            if cv.len() > dim {\n                // Rescale homogeneous coordinates when changing weight\n                let mut old_w = cv[dim];\n                if old_w.abs() < 1e-14 { old_w = 1.0; }\n                let mut new_w = w;\n                if new_w.abs() < 1e-14 { new_w = 1.0; }\n                let scale = new_w / old_w;\n                cv[0] *= scale;\n                if cv.len() > 1 { cv[1] *= scale; }\n                if cv.len() > 2 { cv[2] *= scale; }\n                cv[dim] = w;\n                return true;\n            }\n        }\n        false\n    }",
          "file": "nurbssurface.rs"
        }
