      "name": "Quaternion.__init__",
      "implementations": {
        "python": {
          "sig": "__init__(s=1.0, v=None)",
          "code": "def __init__(self, s=1.0, v=None):\n\n        self.typ = \"Quaternion\"\n        self.guid = str(uuid.uuid4())\n        self.name = \"my_quaternion\"\n        self.s = s\n        self.v = v if v is not None else Vector(0.0, 0.0, 0.0)\n\n    @staticmethod\n    def identity():\n        return Quaternion(1.0, Vector(0.0, 0.0, 0.0))\n\n    @staticmethod\n    def from_sv(s, x, y, z):\n        return Quaternion(s, Vector(x, y, z))\n\n    @staticmethod\n    def from_axis_angle(axis, angle):\n        axis = axis.normalize()\n        half_angle = angle * 0.5\n        s = math.cos(half_angle)\n        v = axis * math.sin(half_angle)\n        return Quaternion(s, v)\n\n    def rotate_vector(self, v):\n        qv = self.v\n        uv = qv.cross(v)\n        uuv = qv.cross(uv)\n        return v + (uv * self.s + uuv) * 2.0\n\n    def magnitude(self):\n        return math.sqrt(\n            self.s * self.s\n            + self.v[0] * self.v[0]\n            + self.v[1] * self.v[1]\n            + self.v[2] * self.v[2]\n        )\n\n    def normalize(self):\n        mag = self.magnitude()\n        if mag > 1e-10:\n            q = Quaternion(self.s / mag, self.v / mag)\n            q.typ = self.typ\n            q.guid = self.guid\n            q.name = self.name\n            return q\n        else:\n            return Quaternion.identity()\n\n    def conjugate(self):\n        q = Quaternion(self.s, self.v * -1.0)\n        q.typ = self.typ\n        q.guid = self.guid\n        q.name = self.name\n        return q\n\n    def __mul__(self, other):\n        if isinstance(other, Quaternion):\n            s = self.s * other.s - self.v.dot(other.v)\n            v = other.v * self.s + self.v * other.s + self.v.cross(other.v)\n            return Quaternion(s, v)\n        raise TypeError(\"Quaternion can only be multiplied with another Quaternion\")\n\n    def __jsondump__(self):\n        \"\"\"Serialize to polymorphic JSON format with type field.\n\n        Returns\n        -------\n        dict\n            Dictionary with 'type', 'guid', 'name', and object fields.\n\n        \"\"\"\n        return {\n            \"type\": f\"{self.__class__.__name__}\",\n            \"guid\": self.guid,\n            \"name\": self.name,\n            \"s\": self.s,\n            \"x\": self.v[0],\n            \"y\": self.v[1],\n            \"z\": self.v[2],\n        }",
          "file": "quaternion.py"
        }
      },
