          "code": "def __init__(self, name=\"my_node\"):\n\n        self.name = name\n        self.guid = str(uuid.uuid4())\n        self._parent = None\n        self._children = []\n        self._tree = None\n\n    def __str__(self):\n        \"\"\"String representation.\"\"\"\n        return f\"TreeNode({self.name}\"\n\n    def __repr__(self):\n        return f\"TreeNode({self.name}, {self.guid}, {len(self.children)} children)\"\n\n    ###########################################################################################\n    # JSON (polymorphic)\n    ###########################################################################################\n\n    def __jsondump__(self) -> dict:\n        \"\"\"Serialize to polymorphic JSON format with type field.\"\"\"\n        return {\n            \"type\": f\"{self.__class__.__name__}\",\n            \"guid\": self.guid,\n            \"name\": self.name,\n            \"children\": [child.__jsondump__() for child in self.children],\n        }\n\n    @classmethod\n    def __jsonload__(\n        cls, data: dict, guid: Optional[str] = None, name: Optional[str] = None\n    ) -> \"TreeNode\":\n        \"\"\"Deserialize from polymorphic JSON format.\"\"\"\n        node = cls(name=data[\"name\"])\n        node.guid = guid if guid is not None else data.get(\"guid\", node.guid)\n        for child_data in data.get(\"children\", []):\n            # Children are polymorphic nodes themselves\n            from .encoders import decode_node\n\n            child_node = decode_node(child_data)\n            node.add(child_node)\n        return node\n\n    ###########################################################################################\n    # Details\n    ###########################################################################################\n\n    @property\n    def is_root(self):\n        return self._parent is None\n\n    @property\n    def is_leaf(self):\n        return not self._children\n\n    @property\n    def is_branch(self):\n        return not self.is_root and not self.is_leaf\n\n    @property\n    def parent(self):\n        return self._parent\n\n    @property\n    def children(self):\n        return self._children\n\n    @property\n    def tree(self):\n        if self.is_root:\n            return self._tree\n        else:\n            return self.parent.tree  # type: ignore\n\n    def add(self, node):\n        \"\"\"Add a child node to this node.\n\n        Parameters\n        ----------\n        node : :class:`TreeNode`\n            The node to add.",
