          "code": "pub fn perpendicular_to(&mut self, v: &Vector) -> bool {\n        // Ported from Python implementation to ensure identical behavior\n        let i: usize;\n        let j: usize;\n        let k: usize;\n        let a: f64;\n        let b: f64;\n\n        if v[1].abs() > v[0].abs() {\n            if v[2].abs() > v[1].abs() {\n                // |v.z| > |v.y| > |v.x|\n                i = 2;\n                j = 1;\n                k = 0;\n                a = v[2];\n                b = -v[1];\n            } else if v[2].abs() >= v[0].abs() {\n                // |v.y| >= |v.z| >= |v.x|\n                i = 1;\n                j = 2;\n                k = 0;\n                a = v[1];\n                b = -v[2];\n            } else {\n                // |v.y| > |v.x| > |v.z|\n                i = 1;\n                j = 0;\n                k = 2;\n                a = v[1];\n                b = -v[0];\n            }\n        } else if v[2].abs() > v[0].abs() {\n            // |v.z| > |v.x| >= |v.y|\n            i = 2;\n            j = 0;\n            k = 1;\n            a = v[2];\n            b = -v[0];\n        } else if v[2].abs() > v[1].abs() {\n            // |v.x| >= |v.z| > |v.y|\n            i = 0;\n            j = 2;\n            k = 1;\n            a = v[0];\n            b = -v[2];\n        } else {\n            // |v.x| >= |v.y| >= |v.z|\n            i = 0;\n            j = 1;\n            k = 2;\n            a = v[0];\n            b = -v[1];\n        }\n\n        let mut coords = [0.0, 0.0, 0.0];\n        coords[i] = b;\n        coords[j] = a;\n        coords[k] = 0.0;\n\n        self._x = coords[0];\n        self._y = coords[1];\n        self._z = coords[2];\n        self.invalidate_magnitude_cache();\n\n        a != 0.0\n    }",
