        "python": {
          "sig": "json_loads(cls, json_string)",
          "code": "def json_loads(cls, json_string):\n\n        \"\"\"Load from JSON string.\"\"\"\n        import json\n        return cls.__jsonload__(json.loads(json_string))\n\n    ###########################################################################################\n    # Protobuf Serialization\n    ###########################################################################################\n\n    def pb_dumps(self):\n        \"\"\"Convert to protobuf binary format.\n\n        Returns\n        -------\n        bytes\n            Serialized protobuf data.\n\n        \"\"\"\n        from .proto import vector_pb2\n        \n        proto = vector_pb2.Vector()\n        proto.x = self._x\n        proto.y = self._y\n        proto.z = self._z\n        proto.name = self.name\n        \n        return proto.SerializeToString()\n\n    @classmethod\n    def pb_loads(cls, data):\n        \"\"\"Create Vector from protobuf binary data.\n\n        Parameters\n        ----------\n        data : bytes\n            Protobuf-encoded vector data.\n\n        Returns\n        -------\n        :class:`Vector`\n            The deserialized Vector.\n\n        \"\"\"\n        from .proto import vector_pb2\n        \n        proto = vector_pb2.Vector()\n        proto.ParseFromString(data)\n        \n        v = cls(proto.x, proto.y, proto.z)\n        v.name = proto.name\n        \n        return v\n\n    def pb_dump(self, filepath):\n        \"\"\"Write protobuf to file.\n\n        Parameters\n        ----------\n        filepath : str\n            Path to the output file.\n\n        \"\"\"\n        data = self.pb_dumps()\n        with open(filepath, 'wb') as f:\n            f.write(data)\n\n    @classmethod\n    def pb_load(cls, filepath):\n        \"\"\"Read protobuf from file.\n\n        Parameters\n        ----------\n        filepath : str\n            Path to the protobuf file.\n\n        Returns\n        -------\n        :class:`Vector`\n            The deserialized Vector.",
          "file": "vector.py"
        },
